//! The `google.protobuf` well-known types, generated by `only-protobuf-build` from its built-in
//! `.proto` files (`import "google/protobuf/timestamp.proto"` in your files refers to these),
//! plus conversions:
//!
//! * [`Timestamp`] ⇄ [`SystemTime`], [`Timestamp::now`];
//! * [`Duration`] ⇄ [`std::time::Duration`];
//! * [`Any::pack`], [`Any::unpack`], [`Any::is`].
//!
//! They do not keep unknown fields.
//!
//! ```
//! use only_protobuf::well_known::{Any, Duration, Timestamp};
//!
//! let t = Timestamp { seconds: 1_700_000_000, nanos: 5 };
//! let any = Any::pack(&t);
//! assert_eq!(any.type_url, "type.googleapis.com/google.protobuf.Timestamp");
//! assert_eq!(any.unpack::<Timestamp>().unwrap(), Some(t));
//! assert_eq!(any.unpack::<Duration>().unwrap(), None);
//!
//! let d = Duration::try_from(std::time::Duration::from_millis(1500)).unwrap();
//! assert_eq!((d.seconds, d.nanos), (1, 500_000_000));
//! ```

use std::{
    fmt,
    time::{SystemTime, UNIX_EPOCH},
};

use crate::{DecodeError, Message, Name};

include!("generated.rs");

/// A time or duration outside what the target type can hold (or a negative duration for
/// `std::time::Duration`, or nanoseconds out of range).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OutOfRangeError;

impl fmt::Display for OutOfRangeError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("value out of range")
    }
}

impl std::error::Error for OutOfRangeError {}

const NANOS: i64 = 1_000_000_000;

impl Timestamp {
    /// The current time.
    pub fn now() -> Timestamp {
        Timestamp::from(SystemTime::now())
    }
}

impl From<SystemTime> for Timestamp {
    fn from(t: SystemTime) -> Timestamp {
        match t.duration_since(UNIX_EPOCH) {
            Ok(d) => Timestamp {
                seconds: i64::try_from(d.as_secs()).unwrap_or(i64::MAX),
                nanos: d.subsec_nanos() as i32,
            },
            Err(e) => {
                let d = e.duration();
                let mut seconds = -i64::try_from(d.as_secs()).unwrap_or(i64::MAX);
                let mut nanos = -(d.subsec_nanos() as i32);
                if nanos < 0 {
                    seconds -= 1;
                    nanos += NANOS as i32;
                }
                Timestamp { seconds, nanos }
            }
        }
    }
}

impl TryFrom<Timestamp> for SystemTime {
    type Error = OutOfRangeError;

    fn try_from(t: Timestamp) -> Result<SystemTime, OutOfRangeError> {
        if !(0..NANOS as i32).contains(&t.nanos) {
            return Err(OutOfRangeError);
        }
        let nanos = std::time::Duration::from_nanos(t.nanos as u64);
        let r = if t.seconds >= 0 {
            UNIX_EPOCH.checked_add(std::time::Duration::from_secs(t.seconds as u64))
        } else {
            UNIX_EPOCH.checked_sub(std::time::Duration::from_secs(t.seconds.unsigned_abs()))
        };
        r.and_then(|r| r.checked_add(nanos)).ok_or(OutOfRangeError)
    }
}

impl TryFrom<std::time::Duration> for Duration {
    type Error = OutOfRangeError;

    fn try_from(d: std::time::Duration) -> Result<Duration, OutOfRangeError> {
        Ok(Duration {
            seconds: i64::try_from(d.as_secs()).map_err(|_| OutOfRangeError)?,
            nanos: d.subsec_nanos() as i32,
        })
    }
}

impl TryFrom<Duration> for std::time::Duration {
    type Error = OutOfRangeError;

    /// Negative durations, and seconds and nanoseconds of different signs, are errors.
    fn try_from(d: Duration) -> Result<std::time::Duration, OutOfRangeError> {
        if d.seconds < 0 || !(0..NANOS as i32).contains(&d.nanos) {
            return Err(OutOfRangeError);
        }
        Ok(std::time::Duration::new(d.seconds as u64, d.nanos as u32))
    }
}

impl Any {
    /// Wraps `m`, with its type URL.
    pub fn pack<M: Message + Name>(m: &M) -> Any {
        Any {
            type_url: M::type_url(),
            value: m.encode_to_vec(),
        }
    }

    /// Whether this holds an `M` (the type URL's last segment is `M`'s full name).
    pub fn is<M: Name>(&self) -> bool {
        self.type_url.rsplit('/').next() == Some(M::FULL_NAME)
    }

    /// The `M` inside, `None` when it holds another type.
    pub fn unpack<M: Message + Name>(&self) -> Result<std::option::Option<M>, DecodeError> {
        if !self.is::<M>() {
            return Ok(None);
        }
        M::decode(&self.value).map(Some)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn time_conversions() {
        let t = SystemTime::now();
        let ts = Timestamp::from(t);
        assert_eq!(SystemTime::try_from(ts).unwrap(), t);
        let before = UNIX_EPOCH - std::time::Duration::from_millis(1500);
        let ts = Timestamp::from(before);
        assert_eq!((ts.seconds, ts.nanos), (-2, 500_000_000));
        assert_eq!(SystemTime::try_from(ts).unwrap(), before);
        assert_eq!(
            SystemTime::try_from(Timestamp {
                seconds: 0,
                nanos: -1
            }),
            Err(OutOfRangeError)
        );
        assert!(
            std::time::Duration::try_from(Duration {
                seconds: -1,
                nanos: 0
            })
            .is_err()
        );
        let d = std::time::Duration::new(3, 7);
        assert_eq!(
            std::time::Duration::try_from(Duration::try_from(d).unwrap()).unwrap(),
            d
        );
    }

    #[test]
    fn wire_and_any() {
        let v = Value {
            kind: Some(value::Kind::StructValue(Struct {
                fields: std::iter::once((
                    "a".to_string(),
                    Value {
                        kind: Some(value::Kind::ListValue(ListValue {
                            values: vec![Value {
                                kind: Some(value::Kind::NullValue(NullValue::NULL_VALUE)),
                            }],
                        })),
                    },
                ))
                .collect(),
            })),
        };
        let b = v.encode_to_vec();
        assert_eq!(Value::decode(&b).unwrap(), v);
        let any = Any::pack(&v);
        assert!(any.is::<Value>());
        assert_eq!(any.unpack::<Value>().unwrap(), Some(v));
        assert!(Any::pack(&Empty {}).value.is_empty());
        let w = Int64Value { value: -1 };
        assert_eq!(w.encode_to_vec().len(), 11);
    }
}
